use code_kb_core::db::{ensure_fts_index, open_read_write};
use std::{path::Path, time::Instant};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let path = std::env::args().nth(1).ok_or("missing database path")?;
    let conn = open_read_write(Path::new(&path))?;
    let version: String = conn.query_row("SELECT sqlite_version()", [], |row| row.get(0))?;
    let started = Instant::now();
    ensure_fts_index(&conn)?;
    let upgrade_ms = started.elapsed().as_secs_f64() * 1000.0;
    let started = Instant::now();
    ensure_fts_index(&conn)?;
    let ready_ms = started.elapsed().as_secs_f64() * 1000.0;
    conn.close().map_err(|(_, err)| err)?;
    println!("{{\"sqlite_version\":\"{version}\",\"upgrade_ms\":{upgrade_ms},\"ready_ms\":{ready_ms}}}");
    Ok(())
}

