#include <stdio.h>
#include <stdlib.h>
#include "sqlite3.h"

int main(int argc, char **argv) {
    if (argc != 3) return 2;
    FILE *file = fopen(argv[2], "rb");
    if (!file || fseek(file, 0, SEEK_END)) return 2;
    long size = ftell(file);
    if (size < 0 || fseek(file, 0, SEEK_SET)) return 2;
    char *sql = malloc((size_t)size + 1);
    if (!sql || fread(sql, 1, (size_t)size, file) != (size_t)size) return 2;
    fclose(file);
    sql[size] = 0;
    sqlite3 *db = NULL;
    if (sqlite3_open_v2(argv[1], &db, SQLITE_OPEN_READONLY, NULL) != SQLITE_OK) return 2;
    if (sqlite3_exec(db, "PRAGMA mmap_size=268435456", NULL, NULL, NULL) != SQLITE_OK) return 2;
    sqlite3_stmt *stmt = NULL;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "%s\n", sqlite3_errmsg(db));
        return 2;
    }
    int rows = 0, status;
    while ((status = sqlite3_step(stmt)) == SQLITE_ROW) rows++;
    if (status != SQLITE_DONE) {
        fprintf(stderr, "%s\n", sqlite3_errmsg(db));
        return 2;
    }
    fprintf(stderr, "sqlite=%s rows=%d vm_steps=%d\n", sqlite3_libversion(), rows,
            sqlite3_stmt_status(stmt, SQLITE_STMTSTATUS_VM_STEP, 0));
    puts("id\tparent\tloops\tvisits\tcycles\tdetail");
    for (int i = 0; ; i++) {
        int id = 0, parent = 0;
        sqlite3_int64 loops = 0, visits = 0, cycles = 0;
        const char *detail = NULL;
        int flags = SQLITE_SCANSTAT_COMPLEX;
        if (sqlite3_stmt_scanstatus_v2(stmt, i, SQLITE_SCANSTAT_SELECTID, flags, &id)) break;
        sqlite3_stmt_scanstatus_v2(stmt, i, SQLITE_SCANSTAT_PARENTID, flags, &parent);
        sqlite3_stmt_scanstatus_v2(stmt, i, SQLITE_SCANSTAT_NLOOP, flags, &loops);
        sqlite3_stmt_scanstatus_v2(stmt, i, SQLITE_SCANSTAT_NVISIT, flags, &visits);
        sqlite3_stmt_scanstatus_v2(stmt, i, SQLITE_SCANSTAT_NCYCLE, flags, &cycles);
        sqlite3_stmt_scanstatus_v2(stmt, i, SQLITE_SCANSTAT_EXPLAIN, flags, &detail);
        printf("%d\t%d\t%lld\t%lld\t%lld\t%s\n", id, parent,
               (long long)loops, (long long)visits, (long long)cycles, detail ? detail : "");
    }
    sqlite3_finalize(stmt);
    sqlite3_close(db);
    free(sql);
    return 0;
}
